    '[{"id": 1, "order": 1, "start": 48.56, "end": 54.0, "startSec": 48.56, "endSec": 54.0, "duration": 5.44, "ru": "Я иду искать! Кто не спрятался, я не виноват.", "text": "Я иду искать! Кто не спрятался, я не виноват.", "vi": "Tớ đi tìm đây! Ai chưa trốn kỹ thì tớ không chịu trách nhiệm đâu đấy.", "translation": "Tớ đi tìm đây! Ai chưa trốn kỹ thì tớ không chịu trách nhiệm đâu đấy.", "text_ru": "Я иду искать! Кто не спрятался, я не виноват.", "translation_vi": "Tớ đi tìm đây! Ai chưa trốn kỹ thì tớ không chịu trách nhiệm đâu đấy.", "text_stressed": "Я иду́ иска́ть! Кто не спря́тался, я не винова́т.", "who": "Вася"}, {"id": 2, "order": 2, "start": 54.24, "end": 58.0, "startSec": 54.24, "endSec": 58.0, "duration": 3.76, "ru": "Фух, успела!", "text": "Фух, успела!", "vi": "Phù, kịp rồi!", "translation": "Phù, kịp rồi!", "text_ru": "Фух, успела!", "translation_vi": "Phù, kịp rồi!", "text_stressed": "Фух, успе́ла!", "who": "Ася"}, {"id": 3, "order": 3, "start": 58.8, "end": 66.8, "startSec": 58.8, "endSec": 66.8, "duration": 8.0, "ru": "Ого, потайная дверь! Фу, как странно пахнет.", "text": "Ого, потайная дверь! Фу, как странно пахнет.", "vi": "Oa, một cánh cửa bí mật! Eo ôi, mùi gì lạ thế này.", "translation": "Oa, một cánh cửa bí mật! Eo ôi, mùi gì lạ thế này.", "text_ru": "Ого, потайная дверь! Фу, как странно пахнет.", "translation_vi": "Oa, một cánh cửa bí mật! Eo ôi, mùi gì lạ thế này.", "text_stressed": "Ого́, потайна́я дверь! Фу, как стра́нно па́хнет.", "who": "Ася"}, {"id": 4, "order": 4, "start": 88.8, "end": 94.8, "startSec": 88.8, "endSec": 94.8, "duration": 6.0, "ru": "Да где же она? Я уже везде посмотрел.", "text": "Да где же она? Я уже везде посмотрел.", "vi": "Cậu ấy ở đâu được nhỉ? Mình đã tìm khắp nơi rồi.", "translation": "Cậu ấy ở đâu được nhỉ? Mình đã tìm khắp nơi rồi.", "text_ru": "Да где же она? Я уже везде посмотрел.", "translation_vi": "Cậu ấy ở đâu được nhỉ? Mình đã tìm khắp nơi rồi.", "text_stressed": "Да где же она́? Я уже́ везде́ посмотре́л.", "who": "Вася"}, {"id": 5, "order": 5, "start": 92.44, "end": 97.04, "startSec": 92.44, "endSec": 97.04, "duration": 4.6, "ru": "Монстр! Вася, там монстр!", "text": "Монстр! Вася, там монстр!", "vi": "Quái vật! Vasya ơi, trong kia có quái vật!", "translation": "Quái vật! Vasya ơi, trong kia có quái vật!", "text_ru": "Монстр! Вася, там монстр!", "translation_vi": "Quái vật! Vasya ơi, trong kia có quái vật!", "text_stressed": "Мо́нстр! Ва́ся, там мо́нстр!", "who": "Ася"}, {"id": 6, "order": 6, "start": 94.76, "end": 102.28, "startSec": 94.76, "endSec": 102.28, "duration": 7.52, "ru": "Это ты что, в сарае пряталась? Так нечестно, мы же договаривались только во дворе!", "text": "Это ты что, в сарае пряталась? Так нечестно, мы же договаривались только во дворе!", "vi": "Cậu trốn trong nhà kho đấy à? Thế là không công bằng, chúng mình đã giao hẹn là chỉ ở trong sân thôi mà!", "translation": "Cậu trốn trong nhà kho đấy à? Thế là không công bằng, chúng mình đã giao hẹn là chỉ ở trong sân thôi mà!", "text_ru": "Это ты что, в сарае пряталась? Так нечестно, мы же договаривались только во дворе!", "translation_vi": "Cậu trốn trong nhà kho đấy à? Thế là không công bằng, chúng mình đã giao hẹn là chỉ ở trong sân thôi mà!", "text_stressed": "Э́то ты что, в сара́е пря́талась? Так нече́стно, мы же догова́ривались то́лько во дворе́!", "who": "Вася"}, {"id": 7, "order": 7, "start": 99.96, "end": 106.24, "startSec": 99.96, "endSec": 106.24, "duration": 6.28, "ru": "Во дворе мест больше не осталось, и я спряталась в сарае, а там монстр!", "text": "Во дворе мест больше не осталось, и я спряталась в сарае, а там монстр!", "vi": "Trong sân hết sạch chỗ rồi nên tớ trốn vào nhà kho, mà ở trong đó có quái vật thật đấy!", "translation": "Trong sân hết sạch chỗ rồi nên tớ trốn vào nhà kho, mà ở trong đó có quái vật thật đấy!", "text_ru": "Во дворе мест больше не осталось, и я спряталась в сарае, а там монстр!", "translation_vi": "Trong sân hết sạch chỗ rồi nên tớ trốn vào nhà kho, mà ở trong đó có quái vật thật đấy!", "text_stressed": "Во дворе́ мест бо́льше не оста́лось, и я спря́талась в сара́е, а там мо́нстр!", "who": "Ася"}, {"id": 8, "order": 8, "start": 104.64, "end": 109.28, "startSec": 104.64, "endSec": 109.28, "duration": 4.64, "ru": "Как начнёт чихать и чавкать!", "text": "Как начнёт чихать и чавкать!", "vi": "Nó cứ hắt xì rồi chóp chép nhai ầm ĩ lên!", "translation": "Nó cứ hắt xì rồi chóp chép nhai ầm ĩ lên!", "text_ru": "Как начнёт чихать и чавкать!", "translation_vi": "Nó cứ hắt xì rồi chóp chép nhai ầm ĩ lên!", "text_stressed": "Как начнёт чиха́ть и ча́вкать!", "who": "Ася"}, {"id": 9, "order": 9, "start": 106.24, "end": 113.08, "startSec": 106.24, "endSec": 113.08, "duration": 6.84, "ru": "Да какой монстр? Тебе показалось! Доски скрипят или ветер.", "text": "Да какой монстр? Тебе показалось! Доски скрипят или ветер.", "vi": "Làm gì có quái vật nào chứ? Cậu tưởng tượng ra thôi! Tiếng ván gỗ cót két hoặc là gió thổi đấy.", "translation": "Làm gì có quái vật nào chứ? Cậu tưởng tượng ra thôi! Tiếng ván gỗ cót két hoặc là gió thổi đấy.", "text_ru": "Да какой монстр? Тебе показалось! Доски скрипят или ветер.", "translation_vi": "Làm gì có quái vật nào chứ? Cậu tưởng tượng ra thôi! Tiếng ván gỗ cót két hoặc là gió thổi đấy.", "text_stressed": "Да како́й мо́нстр? Тебе́ показа́лось! До́ски скрипя́т и́ли ве́тер.", "who": "Вася"}, {"id": 10, "order": 10, "start": 141.24, "end": 149.52, "startSec": 141.24, "endSec": 149.52, "duration": 8.28, "ru": "Папа, там монстр! Он чихает, ворчит, чавкает и плохо пахнет.", "text": "Папа, там монстр! Он чихает, ворчит, чавкает и плохо пахнет.", "vi": "Bố ơi, trong kia có quái vật! Nó hắt xì, gầm gừ, nhai nhóp nhép và mùi hôi lắm ạ.", "translation": "Bố ơi, trong kia có quái vật! Nó hắt xì, gầm gừ, nhai nhóp nhép và mùi hôi lắm ạ.", "text_ru": "Папа, там монстр! Он чихает, ворчит, чавкает и плохо пахнет.", "translation_vi": "Bố ơi, trong kia có quái vật! Nó hắt xì, gầm gừ, nhai nhóp nhép và mùi hôi lắm ạ.", "text_stressed": "Па́па, там мо́нстр! Он чиха́ет, ворчи́т, ча́вкает и пло́хо па́хнет.", "who": "Дети"}, {"id": 11, "order": 11, "start": 147.4, "end": 153.0, "startSec": 147.4, "endSec": 153.0, "duration": 5.6, "ru": "Да ну, какой монстр в нашем сарае? Вам показалось.", "text": "Да ну, какой монстр в нашем сарае? Вам показалось.", "vi": "Thôi nào, làm sao có quái vật trong nhà kho của chúng ta được? Các con nhìn nhầm rồi.", "translation": "Thôi nào, làm sao có quái vật trong nhà kho của chúng ta được? Các con nhìn nhầm rồi.", "text_ru": "Да ну, какой монстр в нашем сарае? Вам показалось.", "translation_vi": "Thôi nào, làm sao có quái vật trong nhà kho của chúng ta được? Các con nhìn nhầm rồi.", "text_stressed": "Да ну, како́й мо́нстр в на́шем сара́е? Вам показа́лось.", "who": "Папа"}, {"id": 12, "order": 12, "start": 150.72, "end": 155.56, "startSec": 150.72, "endSec": 155.56, "duration": 4.84, "ru": "У страха, как говорится, глаза велики.", "text": "У страха, как говорится, глаза велики.", "vi": "Người ta hay bảo: Thần hồn nát thần tính (Khi sợ hãi mọi thứ đều bị phóng đại).", "translation": "Người ta hay bảo: Thần hồn nát thần tính (Khi sợ hãi mọi thứ đều bị phóng đại).", "text_ru": "У страха, как говорится, глаза велики.", "translation_vi": "Người ta hay bảo: Thần hồn nát thần tính (Khi sợ hãi mọi thứ đều bị phóng đại).", "text_stressed": "У стра́ха, как говори́тся, глаза́ велики́.", "who": "Папа"}, {"id": 13, "order": 13, "start": 155.56, "end": 163.24, "startSec": 155.56, "endSec": 163.24, "duration": 7.68, "ru": "Когда пугаешься, всё кажется больше: монстры, долги, проблемы на работе.", "text": "Когда пугаешься, всё кажется больше: монстры, долги, проблемы на работе.", "vi": "Khi bị sợ hãi, cái gì trông cũng to tát hơn: quái vật, nợ nần, rồi áp lực công việc.", "translation": "Khi bị sợ hãi, cái gì trông cũng to tát hơn: quái vật, nợ nần, rồi áp lực công việc.", "text_ru": "Когда пугаешься, всё кажется больше: монстры, долги, проблемы на работе.", "translation_vi": "Khi bị sợ hãi, cái gì trông cũng to tát hơn: quái vật, nợ nần, rồi áp lực công việc.", "text_stressed": "Когда́ пуга́ешься, всё ка́жется бо́льше: мо́нстры, долги́, пробле́мы на рабо́те.", "who": "Папа"}, {"id": 14, "order": 14, "start": 166.36, "end": 171.0, "startSec": 166.36, "endSec": 171.0, "duration": 4.64, "ru": "Не бойтесь, сейчас разберёмся, что там за зверь.", "text": "Не бойтесь, сейчас разберёмся, что там за зверь.", "vi": "Đừng sợ, bây giờ bố sẽ vào kiểm tra xem con thú nào trong đó nhé.", "translation": "Đừng sợ, bây giờ bố sẽ vào kiểm tra xem con thú nào trong đó nhé.", "text_ru": "Не бойтесь, сейчас разберёмся, что там за зверь.", "translation_vi": "Đừng sợ, bây giờ bố sẽ vào kiểm tra xem con thú nào trong đó nhé.", "text_stressed": "Не бо́йтесь, сейча́с разберёмся, что там за зверь.", "who": "Папа"}, {"id": 15, "order": 15, "start": 171.0, "end": 176.0, "startSec": 171.0, "endSec": 176.0, "duration": 5.0, "ru": "А! Медведь!", "text": "А! Медведь!", "vi": "Á! Gấu kìa!", "translation": "Á! Gấu kìa!", "text_ru": "А! Медведь!", "translation_vi": "Á! Gấu kìa!", "text_stressed": "А! Медве́дь!", "who": "Папа"}, {"id": 16, "order": 16, "start": 176.64, "end": 185.12, "startSec": 176.64, "endSec": 185.12, "duration": 8.48, "ru": "Мы же тебе говорили, монстр! Надо срочно звать маму. Она знает, что с медведями делать.", "text": "Мы же тебе говорили, монстр! Надо срочно звать маму. Она знает, что с медведями делать.", "vi": "Tụi con đã bảo bố rồi mà, là quái vật! Phải gọi mẹ gấp thôi, mẹ biết cách xử lý lũ gấu đấy.", "translation": "Tụi con đã bảo bố rồi mà, là quái vật! Phải gọi mẹ gấp thôi, mẹ biết cách xử lý lũ gấu đấy.", "text_ru": "Мы же тебе говорили, монстр! Надо срочно звать маму. Она знает, что с медведями делать.", "translation_vi": "Tụi con đã bảo bố rồi mà, là quái vật! Phải gọi mẹ gấp thôi, mẹ biết cách xử lý lũ gấu đấy.", "text_stressed": "Мы же тебе́ говори́ли, мо́нстр! На́до сро́чно звать ма́му. Она́ зна́ет, что с медве́дями де́лать.", "who": "Дети"}, {"id": 17, "order": 17, "start": 194.32, "end": 200.2, "startSec": 194.32, "endSec": 200.2, "duration": 5.88, "ru": "Мама, пойдём быстрее! Там в сарае монстр!", "text": "Мама, пойдём быстрее! Там в сарае монстр!", "vi": "Mẹ ơi, đi nhanh lên ạ! Trong nhà kho có quái vật kìa mẹ!", "translation": "Mẹ ơi, đi nhanh lên ạ! Trong nhà kho có quái vật kìa mẹ!", "text_ru": "Мама, пойдём быстрее! Там в сарае монстр!", "translation_vi": "Mẹ ơi, đi nhanh lên ạ! Trong nhà kho có quái vật kìa mẹ!", "text_stressed": "Ма́ма, пойдём быстре́е! Там в сара́е мо́нстр!", "who": "Дети"}, {"id": 18, "order": 18, "start": 197.96, "end": 204.84, "startSec": 197.96, "endSec": 204.84, "duration": 6.88, "ru": "Похоже, медведь к нам случайно забрёл и теперь выбраться не может.", "text": "Похоже, медведь к нам случайно забрёл и теперь выбраться не может.", "vi": "Có vẻ con gấu vô tình đi lạc vào đây rồi giờ không tìm được đường ra.", "translation": "Có vẻ con gấu vô tình đi lạc vào đây rồi giờ không tìm được đường ra.", "text_ru": "Похоже, медведь к нам случайно забрёл и теперь выбраться не может.", "translation_vi": "Có vẻ con gấu vô tình đi lạc vào đây rồi giờ không tìm được đường ra.", "text_stressed": "Похо́же, медве́дь к нам случа́йно забрёл и тепе́рь вы́браться не мо́жет.", "who": "Дети"}, {"id": 19, "order": 19, "start": 204.84, "end": 214.48, "startSec": 204.84, "endSec": 214.48, "duration": 9.64, "ru": "На мой взгляд, стоит поторопиться, пока он не начал нервничать. Сердитый медведь может быть очень опасен.", "text": "На мой взгляд, стоит поторопиться, пока он не начал нервничать. Сердитый медведь может быть очень опасен.", "vi": "Theo anh thì nên khẩn trương lên trước khi nó nổi cáu. Một con gấu tức giận có thể rất nguy hiểm đấy.", "translation": "Theo anh thì nên khẩn trương lên trước khi nó nổi cáu. Một con gấu tức giận có thể rất nguy hiểm đấy.", "text_ru": "На мой взгляд, стоит поторопиться, пока он не начал нервничать. Сердитый медведь может быть очень опасен.", "translation_vi": "Theo anh thì nên khẩn trương lên trước khi nó nổi cáu. Một con gấu tức giận có thể rất nguy hiểm đấy.", "text_stressed": "На мой взгляд, сто́ит поторопи́ться, пока́ он не на́чал не́рвничать. Серди́тый медве́дь мо́жет быть о́чень опа́сен.", "who": "Папа"}, {"id": 20, "order": 20, "start": 214.48, "end": 223.36, "startSec": 214.48, "endSec": 223.36, "duration": 8.88, "ru": "Не знаю, как в лесах, а в нашем сарае один точно завёлся. Знаешь, как он рычит? И чихает, и чавкает!", "text": "Не знаю, как в лесах, а в нашем сарае один точно завёлся. Знаешь, как он рычит? И чихает, и чавкает!", "vi": "Con chẳng biết trong rừng thế nào, chứ trong kho nhà mình chắc chắn có một con! Mẹ có biết nó gầm gừ thế nào không? Lại còn hắt xì và nhồm nhoàm nữa!", "translation": "Con chẳng biết trong rừng thế nào, chứ trong kho nhà mình chắc chắn có một con! Mẹ có biết nó gầm gừ thế nào không? Lại còn hắt xì và nhồm nhoàm nữa!", "text_ru": "Не знаю, как в лесах, а в нашем сарае один точно завёлся. Знаешь, как он рычит? И чихает, и чавкает!", "translation_vi": "Con chẳng biết trong rừng thế nào, chứ trong kho nhà mình chắc chắn có một con! Mẹ có biết nó gầm gừ thế nào không? Lại còn hắt xì và nhồm nhoàm nữa!", "text_stressed": "Не зна́ю, как в леса́х, а в на́шем сара́е оди́н то́чно завёлся. Зна́ешь, как он рычи́т? И чиха́ет, и ча́вкает!", "who": "Вася"}, {"id": 21, "order": 21, "start": 223.36, "end": 230.72, "startSec": 223.36, "endSec": 230.72, "duration": 7.36, "ru": "Хорошо. Включаю режим «супермама»! — Ура! Ура!", "text": "Хорошо. Включаю режим «супермама»! — Ура! Ура!", "vi": "Được rồi. Mẹ kích hoạt chế độ \"siêu nhân mẹ\" đây! — Hoan hô! Hoan hô!", "translation": "Được rồi. Mẹ kích hoạt chế độ \"siêu nhân mẹ\" đây! — Hoan hô! Hoan hô!", "text_ru": "Хорошо. Включаю режим «супермама»! — Ура! Ура!", "translation_vi": "Được rồi. Mẹ kích hoạt chế độ \"siêu nhân mẹ\" đây! — Hoan hô! Hoan hô!", "text_stressed": "Хорошо́. Включа́ю режи́м «суперма́ма»! — Ура́! Ура́!", "who": "Мама и дети"}, {"id": 22, "order": 22, "start": 261.2, "end": 271.36, "startSec": 261.2, "endSec": 271.36, "duration": 10.16, "ru": "Знакомьтесь, это Федя, хряк. Ему надо уколы делать, вот хозяева и оставили его у нас на несколько дней.", "text": "Знакомьтесь, это Федя, хряк. Ему надо уколы делать, вот хозяева и оставили его у нас на несколько дней.", "vi": "Làm quen đi nào, đây là chú lợn đực Fedya. Chú ấy cần tiêm thuốc, nên chủ nhà gửi nhờ ở chỗ chúng ta vài ngày.", "translation": "Làm quen đi nào, đây là chú lợn đực Fedya. Chú ấy cần tiêm thuốc, nên chủ nhà gửi nhờ ở chỗ chúng ta vài ngày.", "text_ru": "Знакомьтесь, это Федя, хряк. Ему надо уколы делать, вот хозяева и оставили его у нас на несколько дней.", "translation_vi": "Làm quen đi nào, đây là chú lợn đực Fedya. Chú ấy cần tiêm thuốc, nên chủ nhà gửi nhờ ở chỗ chúng ta vài ngày.", "text_stressed": "Знако́мьтесь, э́то Фе́дя, хряк. Ему́ на́до уко́лы де́лать, вот хозя́ева и оста́вили его́ у нас на не́сколько дней.", "who": "Мама"}, {"id": 23, "order": 23, "start": 271.36, "end": 279.6, "startSec": 271.36, "endSec": 279.6, "duration": 8.24, "ru": "У страха глаза велики! — И вовсе они у тебя не велики, вон какие пуговки маленькие!", "text": "У страха глаза велики! — И вовсе они у тебя не велики, вон какие пуговки маленькие!", "vi": "Đúng là thần hồn nát thần tính! — Mắt cậu có to tí nào đâu, trông bé xíu như cái khuy áo này!", "translation": "Đúng là thần hồn nát thần tính! — Mắt cậu có to tí nào đâu, trông bé xíu như cái khuy áo này!", "text_ru": "У страха глаза велики! — И вовсе они у тебя не велики, вон какие пуговки маленькие!", "translation_vi": "Đúng là thần hồn nát thần tính! — Mắt cậu có to tí nào đâu, trông bé xíu như cái khuy áo này!", "text_stressed": "У стра́ха глаза́ велики́! — И во́все они́ у тебя́ не велики́, вон каки́е пу́говки ма́ленькие!", "who": "Вася и Ася"}, {"id": 24, "order": 24, "start": 298.12, "end": 305.04, "startSec": 298.12, "endSec": 305.04, "duration": 6.92, "ru": "Самые умные животные в мире — это обезьяны, дельфины и свиньи.", "text": "Самые умные животные в мире — это обезьяны, дельфины и свиньи.", "vi": "Những loài động vật thông minh nhất thế giới là khỉ, cá heo và lợn đấy.", "translation": "Những loài động vật thông minh nhất thế giới là khỉ, cá heo và lợn đấy.", "text_ru": "Самые умные животные в мире — это обезьяны, дельфины и свиньи.", "translation_vi": "Những loài động vật thông minh nhất thế giới là khỉ, cá heo và lợn đấy.", "text_stressed": "Са́мые у́мные живо́тные в ми́ре — э́то обезья́ны, дельфи́ны и сви́ньи.", "who": "Ася"}, {"id": 25, "order": 25, "start": 305.04, "end": 311.6, "startSec": 305.04, "endSec": 311.6, "duration": 6.56, "ru": "Свинки даже делят своё жилище на три части: спальню, туалет и столовую. И они совсем не страшные!", "text": "Свинки даже делят своё жилище на три части: спальню, туалет и столовую. И они совсем не страшные!", "vi": "Lợn thậm chí còn chia chỗ ở của mình thành ba phần: phòng ngủ, nhà vệ sinh và phòng ăn. Và chúng chẳng đáng sợ chút nào đâu!", "translation": "Lợn thậm chí còn chia chỗ ở của mình thành ba phần: phòng ngủ, nhà vệ sinh và phòng ăn. Và chúng chẳng đáng sợ chút nào đâu!", "text_ru": "Свинки даже делят своё жилище на три части: спальню, туалет и столовую. И они совсем не страшные!", "translation_vi": "Lợn thậm chí còn chia chỗ ở của mình thành ba phần: phòng ngủ, nhà vệ sinh và phòng ăn. Và chúng chẳng đáng sợ chút nào đâu!", "text_stressed": "Сви́нки да́же де́лят своё жили́ще на три ча́сти: спа́льню, туале́т и столо́вую. И они́ совсе́м не стра́шные!", "who": "Вася"}]'::jsonb,
    '{"source_type": "youtube", "youtube_video_id": "5KOKztPa1yI", "youtube_url": "https://www.youtube.com/watch?v=5KOKztPa1yI", "channel_title": "Ася и Вася", "language": "ru-RU", "transcript_source": "YouTube Russian Verified Auto-captions & Dialogue Alignment", "transcript_verified": true, "video_duration": 317, "sentences_count": 25, "items": [{"id": 1, "order": 1, "start": 48.56, "end": 54.0, "startSec": 48.56, "endSec": 54.0, "duration": 5.44, "ru": "Я иду искать! Кто не спрятался, я не виноват.", "text": "Я иду искать! Кто не спрятался, я не виноват.", "vi": "Tớ đi tìm đây! Ai chưa trốn kỹ thì tớ không chịu trách nhiệm đâu đấy.", "translation": "Tớ đi tìm đây! Ai chưa trốn kỹ thì tớ không chịu trách nhiệm đâu đấy.", "text_ru": "Я иду искать! Кто не спрятался, я не виноват.", "translation_vi": "Tớ đi tìm đây! Ai chưa trốn kỹ thì tớ không chịu trách nhiệm đâu đấy.", "text_stressed": "Я иду́ иска́ть! Кто не спря́тался, я не винова́т.", "who": "Вася"}, {"id": 2, "order": 2, "start": 54.24, "end": 58.0, "startSec": 54.24, "endSec": 58.0, "duration": 3.76, "ru": "Фух, успела!", "text": "Фух, успела!", "vi": "Phù, kịp rồi!", "translation": "Phù, kịp rồi!", "text_ru": "Фух, успела!", "translation_vi": "Phù, kịp rồi!", "text_stressed": "Фух, успе́ла!", "who": "Ася"}, {"id": 3, "order": 3, "start": 58.8, "end": 66.8, "startSec": 58.8, "endSec": 66.8, "duration": 8.0, "ru": "Ого, потайная дверь! Фу, как странно пахнет.", "text": "Ого, потайная дверь! Фу, как странно пахнет.", "vi": "Oa, một cánh cửa bí mật! Eo ôi, mùi gì lạ thế này.", "translation": "Oa, một cánh cửa bí mật! Eo ôi, mùi gì lạ thế này.", "text_ru": "Ого, потайная дверь! Фу, как странно пахнет.", "translation_vi": "Oa, một cánh cửa bí mật! Eo ôi, mùi gì lạ thế này.", "text_stressed": "Ого́, потайна́я дверь! Фу, как стра́нно па́хнет.", "who": "Ася"}, {"id": 4, "order": 4, "start": 88.8, "end": 94.8, "startSec": 88.8, "endSec": 94.8, "duration": 6.0, "ru": "Да где же она? Я уже везде посмотрел.", "text": "Да где же она? Я уже везде посмотрел.", "vi": "Cậu ấy ở đâu được nhỉ? Mình đã tìm khắp nơi rồi.", "translation": "Cậu ấy ở đâu được nhỉ? Mình đã tìm khắp nơi rồi.", "text_ru": "Да где же она? Я уже везде посмотрел.", "translation_vi": "Cậu ấy ở đâu được nhỉ? Mình đã tìm khắp nơi rồi.", "text_stressed": "Да где же она́? Я уже́ везде́ посмотре́л.", "who": "Вася"}, {"id": 5, "order": 5, "start": 92.44, "end": 97.04, "startSec": 92.44, "endSec": 97.04, "duration": 4.6, "ru": "Монстр! Вася, там монстр!", "text": "Монстр! Вася, там монстр!", "vi": "Quái vật! Vasya ơi, trong kia có quái vật!", "translation": "Quái vật! Vasya ơi, trong kia có quái vật!", "text_ru": "Монстр! Вася, там монстр!", "translation_vi": "Quái vật! Vasya ơi, trong kia có quái vật!", "text_stressed": "Мо́нстр! Ва́ся, там мо́нстр!", "who": "Ася"}, {"id": 6, "order": 6, "start": 94.76, "end": 102.28, "startSec": 94.76, "endSec": 102.28, "duration": 7.52, "ru": "Это ты что, в сарае пряталась? Так нечестно, мы же договаривались только во дворе!", "text": "Это ты что, в сарае пряталась? Так нечестно, мы же договаривались только во дворе!", "vi": "Cậu trốn trong nhà kho đấy à? Thế là không công bằng, chúng mình đã giao hẹn là chỉ ở trong sân thôi mà!", "translation": "Cậu trốn trong nhà kho đấy à? Thế là không công bằng, chúng mình đã giao hẹn là chỉ ở trong sân thôi mà!", "text_ru": "Это ты что, в сарае пряталась? Так нечестно, мы же договаривались только во дворе!", "translation_vi": "Cậu trốn trong nhà kho đấy à? Thế là không công bằng, chúng mình đã giao hẹn là chỉ ở trong sân thôi mà!", "text_stressed": "Э́то ты что, в сара́е пря́талась? Так нече́стно, мы же догова́ривались то́лько во дворе́!", "who": "Вася"}, {"id": 7, "order": 7, "start": 99.96, "end": 106.24, "startSec": 99.96, "endSec": 106.24, "duration": 6.28, "ru": "Во дворе мест больше не осталось, и я спряталась в сарае, а там монстр!", "text": "Во дворе мест больше не осталось, и я спряталась в сарае, а там монстр!", "vi": "Trong sân hết sạch chỗ rồi nên tớ trốn vào nhà kho, mà ở trong đó có quái vật thật đấy!", "translation": "Trong sân hết sạch chỗ rồi nên tớ trốn vào nhà kho, mà ở trong đó có quái vật thật đấy!", "text_ru": "Во дворе мест больше не осталось, и я спряталась в сарае, а там монстр!", "translation_vi": "Trong sân hết sạch chỗ rồi nên tớ trốn vào nhà kho, mà ở trong đó có quái vật thật đấy!", "text_stressed": "Во дворе́ мест бо́льше не оста́лось, и я спря́талась в сара́е, а там мо́нстр!", "who": "Ася"}, {"id": 8, "order": 8, "start": 104.64, "end": 109.28, "startSec": 104.64, "endSec": 109.28, "duration": 4.64, "ru": "Как начнёт чихать и чавкать!", "text": "Как начнёт чихать и чавкать!", "vi": "Nó cứ hắt xì rồi chóp chép nhai ầm ĩ lên!", "translation": "Nó cứ hắt xì rồi chóp chép nhai ầm ĩ lên!", "text_ru": "Как начнёт чихать и чавкать!", "translation_vi": "Nó cứ hắt xì rồi chóp chép nhai ầm ĩ lên!", "text_stressed": "Как начнёт чиха́ть и ча́вкать!", "who": "Ася"}, {"id": 9, "order": 9, "start": 106.24, "end": 113.08, "startSec": 106.24, "endSec": 113.08, "duration": 6.84, "ru": "Да какой монстр? Тебе показалось! Доски скрипят или ветер.", "text": "Да какой монстр? Тебе показалось! Доски скрипят или ветер.", "vi": "Làm gì có quái vật nào chứ? Cậu tưởng tượng ra thôi! Tiếng ván gỗ cót két hoặc là gió thổi đấy.", "translation": "Làm gì có quái vật nào chứ? Cậu tưởng tượng ra thôi! Tiếng ván gỗ cót két hoặc là gió thổi đấy.", "text_ru": "Да какой монстр? Тебе показалось! Доски скрипят или ветер.", "translation_vi": "Làm gì có quái vật nào chứ? Cậu tưởng tượng ra thôi! Tiếng ván gỗ cót két hoặc là gió thổi đấy.", "text_stressed": "Да како́й мо́нстр? Тебе́ показа́лось! До́ски скрипя́т и́ли ве́тер.", "who": "Вася"}, {"id": 10, "order": 10, "start": 141.24, "end": 149.52, "startSec": 141.24, "endSec": 149.52, "duration": 8.28, "ru": "Папа, там монстр! Он чихает, ворчит, чавкает и плохо пахнет.", "text": "Папа, там монстр! Он чихает, ворчит, чавкает и плохо пахнет.", "vi": "Bố ơi, trong kia có quái vật! Nó hắt xì, gầm gừ, nhai nhóp nhép và mùi hôi lắm ạ.", "translation": "Bố ơi, trong kia có quái vật! Nó hắt xì, gầm gừ, nhai nhóp nhép và mùi hôi lắm ạ.", "text_ru": "Папа, там монстр! Он чихает, ворчит, чавкает и плохо пахнет.", "translation_vi": "Bố ơi, trong kia có quái vật! Nó hắt xì, gầm gừ, nhai nhóp nhép và mùi hôi lắm ạ.", "text_stressed": "Па́па, там мо́нстр! Он чиха́ет, ворчи́т, ча́вкает и пло́хо па́хнет.", "who": "Дети"}, {"id": 11, "order": 11, "start": 147.4, "end": 153.0, "startSec": 147.4, "endSec": 153.0, "duration": 5.6, "ru": "Да ну, какой монстр в нашем сарае? Вам показалось.", "text": "Да ну, какой монстр в нашем сарае? Вам показалось.", "vi": "Thôi nào, làm sao có quái vật trong nhà kho của chúng ta được? Các con nhìn nhầm rồi.", "translation": "Thôi nào, làm sao có quái vật trong nhà kho của chúng ta được? Các con nhìn nhầm rồi.", "text_ru": "Да ну, какой монстр в нашем сарае? Вам показалось.", "translation_vi": "Thôi nào, làm sao có quái vật trong nhà kho của chúng ta được? Các con nhìn nhầm rồi.", "text_stressed": "Да ну, како́й мо́нстр в на́шем сара́е? Вам показа́лось.", "who": "Папа"}, {"id": 12, "order": 12, "start": 150.72, "end": 155.56, "startSec": 150.72, "endSec": 155.56, "duration": 4.84, "ru": "У страха, как говорится, глаза велики.", "text": "У страха, как говорится, глаза велики.", "vi": "Người ta hay bảo: Thần hồn nát thần tính (Khi sợ hãi mọi thứ đều bị phóng đại).", "translation": "Người ta hay bảo: Thần hồn nát thần tính (Khi sợ hãi mọi thứ đều bị phóng đại).", "text_ru": "У страха, как говорится, глаза велики.", "translation_vi": "Người ta hay bảo: Thần hồn nát thần tính (Khi sợ hãi mọi thứ đều bị phóng đại).", "text_stressed": "У стра́ха, как говори́тся, глаза́ велики́.", "who": "Папа"}, {"id": 13, "order": 13, "start": 155.56, "end": 163.24, "startSec": 155.56, "endSec": 163.24, "duration": 7.68, "ru": "Когда пугаешься, всё кажется больше: монстры, долги, проблемы на работе.", "text": "Когда пугаешься, всё кажется больше: монстры, долги, проблемы на работе.", "vi": "Khi bị sợ hãi, cái gì trông cũng to tát hơn: quái vật, nợ nần, rồi áp lực công việc.", "translation": "Khi bị sợ hãi, cái gì trông cũng to tát hơn: quái vật, nợ nần, rồi áp lực công việc.", "text_ru": "Когда пугаешься, всё кажется больше: монстры, долги, проблемы на работе.", "translation_vi": "Khi bị sợ hãi, cái gì trông cũng to tát hơn: quái vật, nợ nần, rồi áp lực công việc.", "text_stressed": "Когда́ пуга́ешься, всё ка́жется бо́льше: мо́нстры, долги́, пробле́мы на рабо́те.", "who": "Папа"}, {"id": 14, "order": 14, "start": 166.36, "end": 171.0, "startSec": 166.36, "endSec": 171.0, "duration": 4.64, "ru": "Не бойтесь, сейчас разберёмся, что там за зверь.", "text": "Не бойтесь, сейчас разберёмся, что там за зверь.", "vi": "Đừng sợ, bây giờ bố sẽ vào kiểm tra xem con thú nào trong đó nhé.", "translation": "Đừng sợ, bây giờ bố sẽ vào kiểm tra xem con thú nào trong đó nhé.", "text_ru": "Не бойтесь, сейчас разберёмся, что там за зверь.", "translation_vi": "Đừng sợ, bây giờ bố sẽ vào kiểm tra xem con thú nào trong đó nhé.", "text_stressed": "Не бо́йтесь, сейча́с разберёмся, что там за зверь.", "who": "Папа"}, {"id": 15, "order": 15, "start": 171.0, "end": 176.0, "startSec": 171.0, "endSec": 176.0, "duration": 5.0, "ru": "А! Медведь!", "text": "А! Медведь!", "vi": "Á! Gấu kìa!", "translation": "Á! Gấu kìa!", "text_ru": "А! Медведь!", "translation_vi": "Á! Gấu kìa!", "text_stressed": "А! Медве́дь!", "who": "Папа"}, {"id": 16, "order": 16, "start": 176.64, "end": 185.12, "startSec": 176.64, "endSec": 185.12, "duration": 8.48, "ru": "Мы же тебе говорили, монстр! Надо срочно звать маму. Она знает, что с медведями делать.", "text": "Мы же тебе говорили, монстр! Надо срочно звать маму. Она знает, что с медведями делать.", "vi": "Tụi con đã bảo bố rồi mà, là quái vật! Phải gọi mẹ gấp thôi, mẹ biết cách xử lý lũ gấu đấy.", "translation": "Tụi con đã bảo bố rồi mà, là quái vật! Phải gọi mẹ gấp thôi, mẹ biết cách xử lý lũ gấu đấy.", "text_ru": "Мы же тебе говорили, монстр! Надо срочно звать маму. Она знает, что с медведями делать.", "translation_vi": "Tụi con đã bảo bố rồi mà, là quái vật! Phải gọi mẹ gấp thôi, mẹ biết cách xử lý lũ gấu đấy.", "text_stressed": "Мы же тебе́ говори́ли, мо́нстр! На́до сро́чно звать ма́му. Она́ зна́ет, что с медве́дями де́лать.", "who": "Дети"}, {"id": 17, "order": 17, "start": 194.32, "end": 200.2, "startSec": 194.32, "endSec": 200.2, "duration": 5.88, "ru": "Мама, пойдём быстрее! Там в сарае монстр!", "text": "Мама, пойдём быстрее! Там в сарае монстр!", "vi": "Mẹ ơi, đi nhanh lên ạ! Trong nhà kho có quái vật kìa mẹ!", "translation": "Mẹ ơi, đi nhanh lên ạ! Trong nhà kho có quái vật kìa mẹ!", "text_ru": "Мама, пойдём быстрее! Там в сарае монстр!", "translation_vi": "Mẹ ơi, đi nhanh lên ạ! Trong nhà kho có quái vật kìa mẹ!", "text_stressed": "Ма́ма, пойдём быстре́е! Там в сара́е мо́нстр!", "who": "Дети"}, {"id": 18, "order": 18, "start": 197.96, "end": 204.84, "startSec": 197.96, "endSec": 204.84, "duration": 6.88, "ru": "Похоже, медведь к нам случайно забрёл и теперь выбраться не может.", "text": "Похоже, медведь к нам случайно забрёл и теперь выбраться не может.", "vi": "Có vẻ con gấu vô tình đi lạc vào đây rồi giờ không tìm được đường ra.", "translation": "Có vẻ con gấu vô tình đi lạc vào đây rồi giờ không tìm được đường ra.", "text_ru": "Похоже, медведь к нам случайно забрёл и теперь выбраться не может.", "translation_vi": "Có vẻ con gấu vô tình đi lạc vào đây rồi giờ không tìm được đường ra.", "text_stressed": "Похо́же, медве́дь к нам случа́йно забрёл и тепе́рь вы́браться не мо́жет.", "who": "Дети"}, {"id": 19, "order": 19, "start": 204.84, "end": 214.48, "startSec": 204.84, "endSec": 214.48, "duration": 9.64, "ru": "На мой взгляд, стоит поторопиться, пока он не начал нервничать. Сердитый медведь может быть очень опасен.", "text": "На мой взгляд, стоит поторопиться, пока он не начал нервничать. Сердитый медведь может быть очень опасен.", "vi": "Theo anh thì nên khẩn trương lên trước khi nó nổi cáu. Một con gấu tức giận có thể rất nguy hiểm đấy.", "translation": "Theo anh thì nên khẩn trương lên trước khi nó nổi cáu. Một con gấu tức giận có thể rất nguy hiểm đấy.", "text_ru": "На мой взгляд, стоит поторопиться, пока он не начал нервничать. Сердитый медведь может быть очень опасен.", "translation_vi": "Theo anh thì nên khẩn trương lên trước khi nó nổi cáu. Một con gấu tức giận có thể rất nguy hiểm đấy.", "text_stressed": "На мой взгляд, сто́ит поторопи́ться, пока́ он не на́чал не́рвничать. Серди́тый медве́дь мо́жет быть о́чень опа́сен.", "who": "Папа"}, {"id": 20, "order": 20, "start": 214.48, "end": 223.36, "startSec": 214.48, "endSec": 223.36, "duration": 8.88, "ru": "Не знаю, как в лесах, а в нашем сарае один точно завёлся. Знаешь, как он рычит? И чихает, и чавкает!", "text": "Не знаю, как в лесах, а в нашем сарае один точно завёлся. Знаешь, как он рычит? И чихает, и чавкает!", "vi": "Con chẳng biết trong rừng thế nào, chứ trong kho nhà mình chắc chắn có một con! Mẹ có biết nó gầm gừ thế nào không? Lại còn hắt xì và nhồm nhoàm nữa!", "translation": "Con chẳng biết trong rừng thế nào, chứ trong kho nhà mình chắc chắn có một con! Mẹ có biết nó gầm gừ thế nào không? Lại còn hắt xì và nhồm nhoàm nữa!", "text_ru": "Не знаю, как в лесах, а в нашем сарае один точно завёлся. Знаешь, как он рычит? И чихает, и чавкает!", "translation_vi": "Con chẳng biết trong rừng thế nào, chứ trong kho nhà mình chắc chắn có một con! Mẹ có biết nó gầm gừ thế nào không? Lại còn hắt xì và nhồm nhoàm nữa!", "text_stressed": "Не зна́ю, как в леса́х, а в на́шем сара́е оди́н то́чно завёлся. Зна́ешь, как он рычи́т? И чиха́ет, и ча́вкает!", "who": "Вася"}, {"id": 21, "order": 21, "start": 223.36, "end": 230.72, "startSec": 223.36, "endSec": 230.72, "duration": 7.36, "ru": "Хорошо. Включаю режим «супермама»! — Ура! Ура!", "text": "Хорошо. Включаю режим «супермама»! — Ура! Ура!", "vi": "Được rồi. Mẹ kích hoạt chế độ \"siêu nhân mẹ\" đây! — Hoan hô! Hoan hô!", "translation": "Được rồi. Mẹ kích hoạt chế độ \"siêu nhân mẹ\" đây! — Hoan hô! Hoan hô!", "text_ru": "Хорошо. Включаю режим «супермама»! — Ура! Ура!", "translation_vi": "Được rồi. Mẹ kích hoạt chế độ \"siêu nhân mẹ\" đây! — Hoan hô! Hoan hô!", "text_stressed": "Хорошо́. Включа́ю режи́м «суперма́ма»! — Ура́! Ура́!", "who": "Мама и дети"}, {"id": 22, "order": 22, "start": 261.2, "end": 271.36, "startSec": 261.2, "endSec": 271.36, "duration": 10.16, "ru": "Знакомьтесь, это Федя, хряк. Ему надо уколы делать, вот хозяева и оставили его у нас на несколько дней.", "text": "Знакомьтесь, это Федя, хряк. Ему надо уколы делать, вот хозяева и оставили его у нас на несколько дней.", "vi": "Làm quen đi nào, đây là chú lợn đực Fedya. Chú ấy cần tiêm thuốc, nên chủ nhà gửi nhờ ở chỗ chúng ta vài ngày.", "translation": "Làm quen đi nào, đây là chú lợn đực Fedya. Chú ấy cần tiêm thuốc, nên chủ nhà gửi nhờ ở chỗ chúng ta vài ngày.", "text_ru": "Знакомьтесь, это Федя, хряк. Ему надо уколы делать, вот хозяева и оставили его у нас на несколько дней.", "translation_vi": "Làm quen đi nào, đây là chú lợn đực Fedya. Chú ấy cần tiêm thuốc, nên chủ nhà gửi nhờ ở chỗ chúng ta vài ngày.", "text_stressed": "Знако́мьтесь, э́то Фе́дя, хряк. Ему́ на́до уко́лы де́лать, вот хозя́ева и оста́вили его́ у нас на не́сколько дней.", "who": "Мама"}, {"id": 23, "order": 23, "start": 271.36, "end": 279.6, "startSec": 271.36, "endSec": 279.6, "duration": 8.24, "ru": "У страха глаза велики! — И вовсе они у тебя не велики, вон какие пуговки маленькие!", "text": "У страха глаза велики! — И вовсе они у тебя не велики, вон какие пуговки маленькие!", "vi": "Đúng là thần hồn nát thần tính! — Mắt cậu có to tí nào đâu, trông bé xíu như cái khuy áo này!", "translation": "Đúng là thần hồn nát thần tính! — Mắt cậu có to tí nào đâu, trông bé xíu như cái khuy áo này!", "text_ru": "У страха глаза велики! — И вовсе они у тебя не велики, вон какие пуговки маленькие!", "translation_vi": "Đúng là thần hồn nát thần tính! — Mắt cậu có to tí nào đâu, trông bé xíu như cái khuy áo này!", "text_stressed": "У стра́ха глаза́ велики́! — И во́все они́ у тебя́ не велики́, вон каки́е пу́говки ма́ленькие!", "who": "Вася и Ася"}, {"id": 24, "order": 24, "start": 298.12, "end": 305.04, "startSec": 298.12, "endSec": 305.04, "duration": 6.92, "ru": "Самые умные животные в мире — это обезьяны, дельфины и свиньи.", "text": "Самые умные животные в мире — это обезьяны, дельфины и свиньи.", "vi": "Những loài động vật thông minh nhất thế giới là khỉ, cá heo và lợn đấy.", "translation": "Những loài động vật thông minh nhất thế giới là khỉ, cá heo và lợn đấy.", "text_ru": "Самые умные животные в мире — это обезьяны, дельфины и свиньи.", "translation_vi": "Những loài động vật thông minh nhất thế giới là khỉ, cá heo và lợn đấy.", "text_stressed": "Са́мые у́мные живо́тные в ми́ре — э́то обезья́ны, дельфи́ны и сви́ньи.", "who": "Ася"}, {"id": 25, "order": 25, "start": 305.04, "end": 311.6, "startSec": 305.04, "endSec": 311.6, "duration": 6.56, "ru": "Свинки даже делят своё жилище на три части: спальню, туалет и столовую. И они совсем не страшные!", "text": "Свинки даже делят своё жилище на три части: спальню, туалет и столовую. И они совсем не страшные!", "vi": "Lợn thậm chí còn chia chỗ ở của mình thành ba phần: phòng ngủ, nhà vệ sinh và phòng ăn. Và chúng chẳng đáng sợ chút nào đâu!", "translation": "Lợn thậm chí còn chia chỗ ở của mình thành ba phần: phòng ngủ, nhà vệ sinh và phòng ăn. Và chúng chẳng đáng sợ chút nào đâu!", "text_ru": "Свинки даже делят своё жилище на три части: спальню, туалет и столовую. И они совсем не страшные!", "translation_vi": "Lợn thậm chí còn chia chỗ ở của mình thành ba phần: phòng ngủ, nhà vệ sinh và phòng ăn. Và chúng chẳng đáng sợ chút nào đâu!", "text_stressed": "Сви́нки да́же де́лят своё жили́ще на три ча́сти: спа́льню, туале́т и столо́вую. И они́ совсе́м не стра́шные!", "who": "Вася"}]}'::jsonb,
    NOW()
)
